package com.example.jobfinderapp.activities;
import android.content.Intent; import android.os.Bundle; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; import com.example.jobfinderapp.R; import com.example.jobfinderapp.database.DBHelper; import com.example.jobfinderapp.models.User; import com.example.jobfinderapp.utils.UserSession; import java.util.Map;
public class AdminReportActivity extends AppCompatActivity { public void onCreate(Bundle b){super.onCreate(b); DBHelper db=DBHelper.getInstance(this); UserSession s=new UserSession(this); User u=s.isLoggedIn()?db.getUserById(s.getUserId()):null; if(u==null||!DBHelper.ROLE_ADMIN.equals(u.getRole())||!DBHelper.STATUS_ACTIVE.equals(u.getStatus())){s.clear(); Intent i=new Intent(this,LoginActivity.class);i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(i);finish();return;} setContentView(R.layout.activity_admin_report);findViewById(R.id.btnBackReport).setOnClickListener(v->finish()); Map<String,Integer> x=db.getAdminStats(); ((TextView)findViewById(R.id.tvReportUsers)).setText(String.valueOf(x.get("users")));((TextView)findViewById(R.id.tvReportJobs)).setText(String.valueOf(x.get("jobs")));((TextView)findViewById(R.id.tvReportApplications)).setText(String.valueOf(x.get("applications")));((TextView)findViewById(R.id.tvReportPending)).setText(String.valueOf(x.get("pending")));} }
